use malachite::base::num::arithmetic::traits::DivisibleBy;
use malachite::{Integer, Rational};

use crate::grading::try_capacity;
use crate::twisted_involution::compose_matrices;
use crate::{
    AdjointCartanFiber, AdjointFiberElement, CartanClassification, CartanGradingData, Grading,
    InnerClass, LatticeInvolution, ModTwoVector, StructureError, TwistedInvolution, WeylAction,
};

/// Sentinel for a mask the orbit walk has not classified yet.
const CLASS_SENTINEL: u32 = u32::MAX;

/// Masks are `u64`, so the adjoint fiber dimension must fit below the sign of
/// no bit at all — 63 keeps every `1 << dimension` shift in range.
pub(crate) const MAX_MASK_BITS: usize = 63;

/// Stable identifier for one weak real form of one Cartan involution.
///
/// Numbers are assigned by ascending minimal element of each `W_im` orbit in
/// canonical-coordinate integer order. The stage-(d) ordering audit
/// (`SEED_X0_DESIGN.md`) PROVED this coincides with upstream's internal
/// `RealFormNbr` numbering (same ascending orbit seeding, same low-pivot
/// RREF subquotient bases, same coordinate extraction) — these ids are NOT
/// under the adapter deferral; only the interpreter's external
/// `FormNumberMap` order needs an adapter permutation. Class 0 is the orbit
/// of the identity element, the quasisplit normalization. Ids minted by the
/// fundamental Cartan's partition additionally serve as the crate's global
/// real-form numbers, carried by [`crate::RealFormLabels`].
#[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]
pub struct WeakRealFormId(pub(crate) usize);

/// The partition of an adjoint Cartan fiber into `W_im` orbits.
///
/// Orbits correspond to the weak real forms of the inner class at this
/// Cartan involution. The partition owns its class table and one
/// deterministic representative element per class; real-form labels live in
/// [`crate::RealFormLabels`] and the square-class/strong-real layer in
/// [`crate::StrongRealClassification`].
#[derive(Clone, Debug)]
pub struct WeakRealFormPartition {
    adjoint: AdjointCartanFiber,
    class_of_by_mask: Vec<u32>,
    representatives: Vec<AdjointFiberElement>,
}

impl WeakRealFormPartition {
    /// Partition the adjoint fiber underlying validated grading tables.
    ///
    /// `max_elements` is the caller's bound on the enumerated fiber size
    /// `2^dimension`; the walk cost is bounded by that count times the
    /// imaginary rank, so no second knob exists.
    pub fn build(grading: &CartanGradingData, max_elements: usize) -> Result<Self, StructureError> {
        let adjoint = grading.adjoint_fiber();
        let dimension = adjoint.dimension();
        if dimension > MAX_MASK_BITS {
            return Err(StructureError::WeakRealFormResourceLimit {
                resource: "mask bits",
                limit: MAX_MASK_BITS,
            });
        }

        let imaginary_rank = grading.imaginary_rank();
        let mut base = try_capacity::<bool>(imaginary_rank)?;
        let mut alpha_columns = try_capacity::<u64>(imaginary_rank)?;
        let mut m_alpha_masks = try_capacity::<u64>(imaginary_rank)?;
        for imaginary_index in 0..imaginary_rank {
            base.push(
                grading
                    .base_grading()
                    .is_noncompact(imaginary_index)
                    .ok_or(StructureError::IndexOutOfRange {
                        index: imaginary_index,
                        upper_bound: imaginary_rank,
                    })?,
            );
            let mut column = 0_u64;
            for adjoint_basis_index in 0..dimension {
                let shift = grading.grading_shift(adjoint_basis_index).ok_or(
                    StructureError::IndexOutOfRange {
                        index: adjoint_basis_index,
                        upper_bound: dimension,
                    },
                )?;
                if shift.is_noncompact(imaginary_index) == Some(true) {
                    column |= 1_u64 << adjoint_basis_index;
                }
            }
            let element = grading.adjoint_m_alpha(imaginary_index).ok_or(
                StructureError::IndexOutOfRange {
                    index: imaginary_index,
                    upper_bound: imaginary_rank,
                },
            )?;
            let translation = mask_of(adjoint, element)?;
            alpha_columns.push(column);
            m_alpha_masks.push(translation);
        }

        let orbits = walk_mask_orbits(
            dimension,
            max_elements,
            &base,
            &alpha_columns,
            &m_alpha_masks,
            weak_limit_error,
        )?;
        let mut representatives = try_capacity(orbits.representative_masks.len())?;
        for &mask in &orbits.representative_masks {
            representatives.push(element_of(adjoint, mask)?);
        }

        Ok(Self {
            adjoint: adjoint.clone(),
            class_of_by_mask: orbits.class_of_by_mask,
            representatives,
        })
    }

    /// The number of weak real forms at this Cartan involution.
    pub fn class_count(&self) -> usize {
        self.representatives.len()
    }

    /// The id-typed enumeration of `0..class_count()`.
    pub fn classes(&self) -> impl ExactSizeIterator<Item = WeakRealFormId> {
        (0..self.representatives.len()).map(WeakRealFormId)
    }

    /// The weak real form whose orbit contains this element.
    pub fn class_of(
        &self,
        element: &AdjointFiberElement,
    ) -> Result<WeakRealFormId, StructureError> {
        let mask = mask_of(&self.adjoint, element)?;
        self.class_of_mask(mask)
    }

    /// The weak real form whose orbit contains the element whose canonical
    /// coordinates are `mask` (bit `i` = adjoint basis direction `i`). This
    /// is the crate's fiber-element enumeration order, so it backs
    /// language-level per-element queries such as `fiber_partition`.
    pub fn class_of_mask(&self, mask: u64) -> Result<WeakRealFormId, StructureError> {
        let index = index_from_mask(mask)?;
        let class =
            self.class_of_by_mask
                .get(index)
                .copied()
                .ok_or(StructureError::IndexOutOfRange {
                    index,
                    upper_bound: self.class_of_by_mask.len(),
                })?;
        usize::try_from(class)
            .map_err(|_| StructureError::ArithmeticOverflow)
            .map(WeakRealFormId)
    }

    /// The minimal element of a class in canonical-coordinate integer order.
    /// Bounded by `class_count()`.
    pub fn class_representative(&self, class: WeakRealFormId) -> Option<&AdjointFiberElement> {
        self.representatives.get(class.0)
    }

    /// The class of the identity element: the quasisplit weak real form,
    /// which is class 0 under this crate's ascending-minimal numbering.
    pub fn quasisplit_class(&self) -> WeakRealFormId {
        WeakRealFormId(0)
    }

    /// The validated adjoint fiber this partition was computed against.
    pub fn adjoint_fiber(&self) -> &AdjointCartanFiber {
        &self.adjoint
    }
}

/// Attribute a raw Atlas-language torus factor at one stored Cartan
/// representative to its global weak real form.
///
/// This is the representative-level kernel of upstream `real_form_of`
/// (`atlas-types.w:3878-3894`, `innerclass.cpp:1305-1355`): first apply the
/// dual fixed-point projection `v -> (v + v theta) / 2` using Atlas's row-
/// vector/right-product convention. Integral pairings of the projected value
/// make the square central; even pairings mark noncompact simple-imaginary
/// roots, the grading identifies a local adjoint-fiber orbit, and the Cartan's
/// label maps that orbit to the fundamental weak-form numbering.
///
/// `twisted` must be exactly a representative stored by `classification`.
/// Moving a general twisted involution to that representative also transports
/// its torus factor through table-backed Tits cross actions; this helper does
/// not silently build or extend that table. The later `minimal_torus_part`
/// descent additionally needs the still-separate inverse-Cayley operation.
pub fn weak_real_form_at_representative(
    inner_class: &InnerClass,
    classification: &CartanClassification,
    twisted: &TwistedInvolution,
    raw_torus_factor: &[Rational],
) -> Result<WeakRealFormId, StructureError> {
    let rank = inner_class.datum().lattice_rank();
    if raw_torus_factor.len() != rank {
        return Err(StructureError::RankMismatch {
            expected: rank,
            actual: raw_torus_factor.len(),
        });
    }

    // CartanClassification does not retain an InnerClass handle. Its first
    // representative is nevertheless the normalized distinguished
    // involution, so reconstruct that value as an explicit provenance gate
    // before any class lookup. The work is bounded by the owned datum and root
    // system; a future retained provenance token could make this check cheap.
    let fundamental = TwistedInvolution::new(
        inner_class.datum(),
        inner_class.root_system(),
        inner_class.distinguished_involution().involution(),
        WeylAction::identity(inner_class.datum())?,
    )?;
    if classification
        .cartan_classes()
        .first()
        .map(|class| class.representative())
        != Some(&fundamental)
    {
        return Err(StructureError::DatumMismatch);
    }

    if twisted.weyl_action().datum() != inner_class.datum() {
        return Err(StructureError::DatumMismatch);
    }
    let delta = inner_class.distinguished_involution().involution();
    let theta = twisted.root_involution().involution();
    if compose_matrices(twisted.weyl_action().matrix(), delta.weight_matrix())?
        != theta.weight_matrix()
        || compose_matrices(
            twisted.weyl_action().coweight_matrix(),
            delta.coweight_matrix(),
        )? != theta.coweight_matrix()
    {
        return Err(StructureError::DistinguishedInvolutionMismatch);
    }

    let cartan = classification
        .cartan_classes()
        .iter()
        .find(|class| class.representative() == twisted)
        .ok_or(StructureError::CartanClassificationInvariantViolation {
            invariant: "synthetic real-form Cartan representative",
        })?;
    let torus_factor = project_torus_factor(theta, raw_torus_factor)?;

    // Equivalently to upstream's even-pairing check on the doubled
    // projection, the projected factor must pair integrally with every simple
    // root. Check this before extracting the imaginary grading so a real
    // Cartan, whose imaginary basis is empty, cannot bypass the gate.
    for root in inner_class.datum().simple_roots() {
        integral_pairing(&torus_factor, root.as_slice())?;
    }

    let mut noncompact = try_capacity(cartan.grading().imaginary_rank())?;
    for (imaginary_index, &root_id) in cartan.grading().imaginary_simple_roots().iter().enumerate()
    {
        let root = inner_class.root_system().root(root_id).ok_or(
            StructureError::CartanClassificationInvariantViolation {
                invariant: "synthetic real-form imaginary root",
            },
        )?;
        if integral_pairing(&torus_factor, root.as_slice())?.divisible_by(&Integer::from(2)) {
            noncompact.push(imaginary_index);
        }
    }
    let grading = Grading::from_noncompact(cartan.grading().imaginary_rank(), noncompact)?;
    let element = cartan.grading().element_from_grading(&grading)?;
    let local = cartan.partition().class_of(&element)?;
    cartan
        .labels()
        .label(local)
        .ok_or(StructureError::CartanClassificationInvariantViolation {
            invariant: "synthetic real-form label",
        })
}

fn project_torus_factor(
    theta: &LatticeInvolution,
    raw_torus_factor: &[Rational],
) -> Result<Vec<Rational>, StructureError> {
    let rank = theta.lattice_rank();
    if raw_torus_factor.len() != rank {
        return Err(StructureError::RankMismatch {
            expected: rank,
            actual: raw_torus_factor.len(),
        });
    }
    let matrix = theta.weight_matrix();
    let mut projected = try_capacity(rank)?;
    for column in 0..rank {
        let mut transported = Rational::from(0);
        for (row, theta_row) in matrix.iter().enumerate() {
            transported += &raw_torus_factor[row] * Rational::from(theta_row[column]);
        }
        projected.push((&raw_torus_factor[column] + transported) / Rational::from(2));
    }
    Ok(projected)
}

fn integral_pairing(torus_factor: &[Rational], root: &[i32]) -> Result<Integer, StructureError> {
    if root.len() != torus_factor.len() {
        return Err(StructureError::RankMismatch {
            expected: root.len(),
            actual: torus_factor.len(),
        });
    }
    let pairing = torus_factor
        .iter()
        .zip(root)
        .fold(Rational::from(0), |sum, (value, &coordinate)| {
            sum + value * Rational::from(coordinate)
        });
    Integer::try_from(pairing).map_err(|_| StructureError::InvalidStrongTorusFactor)
}

fn weak_limit_error(resource: &'static str, limit: usize) -> StructureError {
    StructureError::WeakRealFormResourceLimit { resource, limit }
}

/// The shared `W_im` mask-orbit walk over a `2^dimension` mod-two group.
///
/// The transition rule is `FiberAction`: at imaginary index `i`, a mask
/// whose grading bit (`base[i] XOR parity(mask AND alpha_columns[i])`) is
/// noncompact translates by `m_alpha_masks[i]`. Classes are numbered by
/// ascending minimal mask; `representative_masks[c]` is class `c`'s minimal
/// mask. The caller supplies the resource-limit constructor so error
/// attribution names the stage whose walk tripped.
pub(crate) struct MaskOrbits {
    pub(crate) class_of_by_mask: Vec<u32>,
    pub(crate) representative_masks: Vec<u64>,
}

pub(crate) fn walk_mask_orbits(
    dimension: usize,
    max_elements: usize,
    base: &[bool],
    alpha_columns: &[u64],
    m_alpha_masks: &[u64],
    limit_error: fn(&'static str, usize) -> StructureError,
) -> Result<MaskOrbits, StructureError> {
    if dimension > MAX_MASK_BITS {
        return Err(limit_error("mask bits", MAX_MASK_BITS));
    }
    // The mask-bits gate above keeps this shift in range; the comparison is
    // deliberately unsaturated so `dimension == 64` cannot slip past a
    // `usize::MAX` limit on a 64-bit host.
    let required = 1_u128 << dimension;
    if required > widened(max_elements) {
        return Err(limit_error("fiber elements", max_elements));
    }
    let element_count =
        usize::try_from(required).map_err(|_| StructureError::ArithmeticOverflow)?;
    let imaginary_rank = base.len();
    // Involutivity of each generator is `<alpha_s, alpha_s_vee> = 2` read
    // mod two through validated grading tables; upstream only ever assumes
    // each generator permutes the group.
    for (column, translation) in alpha_columns.iter().zip(m_alpha_masks) {
        debug_assert_eq!((translation & column).count_ones() % 2, 0);
    }

    let mut class_of_by_mask = try_capacity::<u32>(element_count)?;
    class_of_by_mask.resize(element_count, CLASS_SENTINEL);
    let mut pending = try_capacity::<u64>(element_count)?;
    let mut class_count: usize = 0;
    for seed_index in 0..element_count {
        if class_of_by_mask[seed_index] != CLASS_SENTINEL {
            continue;
        }
        let class = seeded_class(class_count, limit_error)?;
        class_of_by_mask[seed_index] = class;
        pending.push(mask_from_index(seed_index)?);
        while let Some(mask) = pending.pop() {
            for imaginary_index in 0..imaginary_rank {
                let paired = (mask & alpha_columns[imaginary_index]).count_ones() & 1 == 1;
                if base[imaginary_index] != paired {
                    // Noncompact at this root: translate by its m_alpha.
                    let image = mask ^ m_alpha_masks[imaginary_index];
                    let image_index = index_from_mask(image)?;
                    if class_of_by_mask[image_index] == CLASS_SENTINEL {
                        class_of_by_mask[image_index] = class;
                        pending.push(image);
                    }
                }
            }
        }
        class_count = class_count
            .checked_add(1)
            .ok_or(StructureError::ArithmeticOverflow)?;
    }

    // Classes are numbered by ascending minimal mask, so the first ascending
    // occurrence of each class number is its representative.
    let mut representative_masks = try_capacity(class_count)?;
    for (index, &class) in class_of_by_mask.iter().enumerate() {
        let class = usize::try_from(class).map_err(|_| StructureError::ArithmeticOverflow)?;
        if class == representative_masks.len() {
            representative_masks.push(mask_from_index(index)?);
        }
    }
    debug_assert_eq!(representative_masks.len(), class_count);

    Ok(MaskOrbits {
        class_of_by_mask,
        representative_masks,
    })
}

/// Convert the next class ordinal into a stored class number, rejecting the
/// sentinel. This guard is reachable in principle: a simply-connected product
/// has zero adjoint `m_alpha` vectors, so every mask is a singleton class.
fn seeded_class(
    class_count: usize,
    limit_error: fn(&'static str, usize) -> StructureError,
) -> Result<u32, StructureError> {
    match u32::try_from(class_count) {
        Ok(class) if class != CLASS_SENTINEL => Ok(class),
        _ => Err(limit_error("classes", CLASS_SENTINEL as usize)),
    }
}

fn mask_of(
    fiber: &AdjointCartanFiber,
    element: &AdjointFiberElement,
) -> Result<u64, StructureError> {
    debug_assert!(fiber.dimension() <= MAX_MASK_BITS);
    let coordinates = fiber.coordinates(element)?;
    let mut mask = 0_u64;
    for index in 0..fiber.dimension() {
        if coordinates.bit(index) == Some(true) {
            mask |= 1_u64 << index;
        }
    }
    Ok(mask)
}

fn element_of(
    fiber: &AdjointCartanFiber,
    mask: u64,
) -> Result<AdjointFiberElement, StructureError> {
    let mut representative = ModTwoVector::zero(fiber.datum().rank())?;
    for (index, basis) in fiber.basis_representatives().iter().enumerate() {
        if mask & (1_u64 << index) != 0 {
            representative.xor_assign(basis)?;
        }
    }
    fiber.element_from_ambient(representative)
}

fn mask_from_index(index: usize) -> Result<u64, StructureError> {
    u64::try_from(index).map_err(|_| StructureError::ArithmeticOverflow)
}

fn index_from_mask(mask: u64) -> Result<usize, StructureError> {
    usize::try_from(mask).map_err(|_| StructureError::ArithmeticOverflow)
}

fn widened(value: usize) -> u128 {
    u128::try_from(value).unwrap_or(u128::MAX)
}

#[cfg(test)]
mod tests {
    use crate::integer_lattice::IntegerLatticeBudget;
    use crate::{
        AdjointFiberBudget, BasedRootDatum, CartanClassificationBudget, CartanFiber, Coweight,
        LatticeInvolution, RootInvolutionData, RootSystem, Weight,
    };

    use super::*;

    fn integer_budget() -> IntegerLatticeBudget {
        IntegerLatticeBudget::new(64, 100_000, 100_000, 128)
    }

    fn adjoint_budget() -> AdjointFiberBudget {
        AdjointFiberBudget::new(integer_budget(), 50_000, 100_000)
    }

    fn classification_budget(weyl_budget: usize) -> CartanClassificationBudget {
        CartanClassificationBudget::new(integer_budget(), adjoint_budget(), weyl_budget, 8, 8)
    }

    fn simply_connected_a1() -> (InnerClass, CartanClassification) {
        let datum = BasedRootDatum::from_simple_data(
            1,
            vec![vec![2]],
            vec![Weight::new(vec![2])],
            vec![Coweight::new(vec![1])],
        )
        .unwrap();
        let inner_class = InnerClass::new(
            datum.clone(),
            LatticeInvolution::identity(&datum).unwrap(),
            2,
        )
        .unwrap();
        let classification =
            CartanClassification::build(&inner_class, &classification_budget(2)).unwrap();
        (inner_class, classification)
    }

    fn grading_chain(
        datum: &BasedRootDatum,
        involution: LatticeInvolution,
        max_roots: usize,
    ) -> (AdjointCartanFiber, CartanGradingData) {
        let roots = RootSystem::enumerate(datum, max_roots).unwrap();
        let data = RootInvolutionData::new(&roots, involution.clone()).unwrap();
        let source = CartanFiber::build(&involution, &integer_budget()).unwrap();
        let adjoint = AdjointCartanFiber::build(&roots, &data, &source, &adjoint_budget()).unwrap();
        let grading = CartanGradingData::build(&roots, &data, &adjoint).unwrap();
        (adjoint, grading)
    }

    fn ambient(rank: usize, indices: impl IntoIterator<Item = usize>) -> ModTwoVector {
        ModTwoVector::from_ones(rank, indices).unwrap()
    }

    #[test]
    fn synthetic_a1_representatives_match_the_frozen_weak_form_anchors() {
        let (inner_class, classification) = simply_connected_a1();
        let compact_cartan = classification.cartan_classes()[0].representative();
        let split_cartan = classification.cartan_classes()[1].representative();
        let zero = Rational::from(0);
        let half = Rational::from(1) / Rational::from(2);

        assert_eq!(
            weak_real_form_at_representative(
                &inner_class,
                &classification,
                compact_cartan,
                std::slice::from_ref(&zero),
            ),
            Ok(WeakRealFormId(0))
        );
        assert_eq!(
            weak_real_form_at_representative(
                &inner_class,
                &classification,
                split_cartan,
                std::slice::from_ref(&zero),
            ),
            Ok(WeakRealFormId(0))
        );
        assert_eq!(
            weak_real_form_at_representative(
                &inner_class,
                &classification,
                compact_cartan,
                std::slice::from_ref(&half),
            ),
            Ok(WeakRealFormId(1))
        );
    }

    #[test]
    fn synthetic_a1_gates_rank_and_noncentral_raw_factors() {
        let (inner_class, classification) = simply_connected_a1();
        let representative = classification.cartan_classes()[0].representative();

        assert_eq!(
            weak_real_form_at_representative(&inner_class, &classification, representative, &[]),
            Err(StructureError::RankMismatch {
                expected: 1,
                actual: 0,
            })
        );
        let quarter = Rational::from(1) / Rational::from(4);
        assert_eq!(
            weak_real_form_at_representative(
                &inner_class,
                &classification,
                representative,
                std::slice::from_ref(&quarter),
            ),
            Err(StructureError::InvalidStrongTorusFactor)
        );
    }

    #[test]
    fn synthetic_a1_rejects_a_foreign_same_rank_classification_first() {
        let (inner_class, _) = simply_connected_a1();
        let foreign_datum = BasedRootDatum::standard(vec![vec![2]]).unwrap();
        let foreign_inner = InnerClass::new(
            foreign_datum.clone(),
            LatticeInvolution::identity(&foreign_datum).unwrap(),
